import 'package:cloud_firestore/cloud_firestore.dart';class StoryItem{final String type,url;final String? text;final Duration duration;const StoryItem({required this.type,this.url='',this.text,this.duration=const Duration(seconds:5)});factory StoryItem.fromMap(Map<String,dynamic>d){final s=((d['durationSeconds']as num?)?.toInt()??5).clamp(3,15).toInt();return StoryItem(type:d['type']?.toString()??'text',url:d['url']?.toString()??'',text:d['text']?.toString(),duration:Duration(seconds:s));}Map<String,dynamic>toMap()=>{'type':type,'url':url,'text':text,'durationSeconds':duration.inSeconds};}class UserStatusModel{final String id,userId,userName;final String? userImage;final List<StoryItem> stories;final DateTime createdAt,expiresAt;final bool isViewed;const UserStatusModel({required this.id,required this.userId,required this.userName,required this.stories,required this.createdAt,required this.expiresAt,this.userImage,this.isViewed=false});bool get isValid=>DateTime.now().isBefore(expiresAt);factory UserStatusModel.fromDocument(DocumentSnapshot<Map<String,dynamic>>doc,{bool isViewed=false}){final d=doc.data()??{};final c=(d['createdAt']as Timestamp?)?.toDate()??DateTime.now();final e=(d['expiresAt']as Timestamp?)?.toDate()??c.add(const Duration(hours:24));final raw=d['stories'];final stories=raw is List?raw.whereType<Map>().map((x)=>StoryItem.fromMap(Map<String,dynamic>.from(x))).toList():<StoryItem>[];return UserStatusModel(id:doc.id,userId:d['userId']?.toString()??'',userName:d['userName']?.toString().trim().isNotEmpty==true?d['userName'].toString():'مستخدم',userImage:d['userImage']?.toString(),stories:stories,createdAt:c,expiresAt:e,isViewed:isViewed);}}